"""G016 sampler: every 5 s, one CSV line: mono_ns, unix_s, height, utime+stime ticks of the node, its block-I/O delay ticks
(delayacct, needs kernel.task_delayacct=1), its VmRSS/RssAnon kB, and the cgroup's memory.current / anon / file /
file_dirty / file_writeback / workingset_refault_file (if a cgroup path is given).
usage: python3 -I sampler.py <rpc port> <node pid> <out csv> [<cgroup dir>]"""
import json, sys, time, urllib.request
port, pid, out = sys.argv[1], int(sys.argv[2]), sys.argv[3]
cg = sys.argv[4] if len(sys.argv) > 4 else ""
def height():
    try:
        with urllib.request.urlopen("http://127.0.0.1:%s/get_height" % port, timeout=4) as r:
            return json.load(r).get("height", "")
    except Exception:
        return ""
def proc():
    try:
        f = open("/proc/%d/stat" % pid).read().rsplit(")", 1)[1].split()
        cpu = int(f[11]) + int(f[12])
        blkio = int(f[39])
        st = dict(l.split(":", 1) for l in open("/proc/%d/status" % pid) if ":" in l)
        return cpu, blkio, st["VmRSS"].split()[0], st["RssAnon"].split()[0]
    except Exception:
        return None
def cgstat():
    if not cg:
        return ["", "", "", "", "", ""]
    try:
        cur = open(cg + "/memory.current").read().strip()
        m = dict(l.split() for l in open(cg + "/memory.stat"))
        return [cur, m.get("anon", ""), m.get("file", ""), m.get("file_dirty", ""), m.get("file_writeback", ""), m.get("workingset_refault_file", "")]
    except Exception:
        return ["", "", "", "", "", ""]
with open(out, "w") as f:
    f.write("mono_ns,unix_s,height,cpu_ticks,blkio_ticks,vmrss_kb,rssanon_kb,cg_current,cg_anon,cg_file,cg_file_dirty,cg_file_writeback,cg_refault_file\n")
    while True:
        p = proc()
        if p is None:
            break
        f.write(",".join(str(x) for x in [time.monotonic_ns(), "%.3f" % time.time(), height(), *p, *cgstat()]) + "\n")
        f.flush()
        time.sleep(5)
